record.field:
# Supprimer l'avance corrompue en la mettant d'abord en brouillon
bad_advances = env['casa.client.advance'].search([('comment', '=', "Paiement transport /")])
if bad_advances:
    bad_advances.write({'state': 'draft'})
    bad_advances.sudo().with_context(is_transport_operation=True).unlink()

for record in records:
    if record.name == '/':
        new_name = env['ir.sequence'].next_by_code('suivi.transport.tanger.operation')
        record.write({'name': new_name, 'state': 'initial'})

for record in records:
    if record.state == 'initial':
        record.action_pay()

for record in records:
    if record.state == 'paid':
        record.action_validate()
